var PAGE3 = 1e3;
async function fetchAll4(table, orderBy = "created_at") {
  const out = [];
  for (let from = 0; ; from += PAGE3) {
    const { data, error } = await supabase.from(table).select("*").order(orderBy, { ascending: true }).range(from, from + PAGE3 - 1);
    if (error) throw new Error(error.message);
    const rows = data ?? [];
    out.push(...rows);
    if (rows.length < PAGE3) break;
  }
  return out;
}
