var db = supabase;
var PAGE4 = 1e3;
async function fetchAll5(table, orderBy = "created_at") {
  const out = [];
  for (let from = 0; ; from += PAGE4) {
    const { data, error } = await db.from(table).select("*").order(orderBy, { ascending: true }).range(from, from + PAGE4 - 1);
    if (error) throw new Error(error.message);
    const rows = data ?? [];
    out.push(...rows);
    if (rows.length < PAGE4) break;
  }
  return out;
}
